[package]
name = "openagents-cli"
# The CLI release version, shared with Coder and its bundled Microcoder.
# The release scripts check this value before naming downloadable artifacts.
version = "1.0.0-rc.5"
edition.workspace = true
rust-version.workspace = true
publish.workspace = true
description = "The openagents command: one program that reaches every OpenAgents surface an agent needs, over Nostr."

